package com.cyancoder.tenant.service;import com.cyancoder.tenant.api.TenantContracts.*;import com.cyancoder.tenant.model.*;import com.cyancoder.tenant.repository.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class TenantInvitationService{private final TenantInvitationRepository invitations;private final TenantRoleRepository roles;private final TenantMembershipRepository memberships;private final TenantTeamService team;private final IdentityDirectoryClient identities;private final NotificationInvitationClient notifications;public TenantInvitationService(TenantInvitationRepository i,TenantRoleRepository r,TenantMembershipRepository m,TenantTeamService t,IdentityDirectoryClient identities,NotificationInvitationClient n){invitations=i;roles=r;memberships=m;team=t;this.identities=identities;notifications=n;}
 public List<TenantInvitationView> list(String tenant){team.requireTeamManager(tenant);return invitations.findByTenantKeyOrderByCreatedAtDesc(tenant).stream().map(this::view).toList();}
 @Transactional public TenantInvitationView create(String tenant,CreateInvitationRequest request){team.requireTeamManager(tenant);roles.findByTenantKeyAndRoleKey(tenant,request.roleKey()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Role not found"));String token=UUID.randomUUID()+"."+UUID.randomUUID();Instant now=Instant.now();TenantInvitationEntity e=new TenantInvitationEntity();e.setInvitationId(UUID.randomUUID().toString());e.setTenantKey(tenant);e.setEmail(request.email().trim().toLowerCase(Locale.ROOT));e.setRoleKey(request.roleKey());e.setTokenHash(hash(token));e.setStatus("PENDING");e.setDeliveryStatus("PENDING");e.setCreatedBy(team.currentActor());e.setCreatedAt(now);e.setExpiresAt(now.plus(Duration.ofHours(request.expiresInHours()==null?24:request.expiresInHours())));invitations.save(e);e.setDeliveryStatus(notifications.send(tenant,e.getInvitationId(),e.getEmail(),token,e.getExpiresAt()));return view(invitations.save(e));}
 @Transactional public TenantUserSummary accept(AcceptInvitationRequest request){TenantInvitationEntity e=invitations.findByTokenHash(hash(request.token())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invitation not found"));if(!"PENDING".equals(e.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invitation is not pending");if(e.getExpiresAt().isBefore(Instant.now())){e.setStatus("EXPIRED");invitations.save(e);throw new ResponseStatusException(HttpStatus.GONE,"Invitation expired");}if(memberships.findByTenantKeyAndUsername(e.getTenantKey(),request.username()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"User is already a tenant member");var identity=identities.provision(request.username(),request.password(),e.getEmail(),request.phoneNumber(),request.mfaRequired(),IdentityDirectoryClient.panelRoleForTenantRole(e.getRoleKey()));Instant now=Instant.now();TenantMembershipEntity m=new TenantMembershipEntity();m.setMembershipId(e.getTenantKey()+"|"+identity.username());m.setTenantKey(e.getTenantKey());m.setUsername(identity.username());m.setRoleKey(e.getRoleKey());m.setActive(true);m.setCreatedAt(now);m.setUpdatedAt(now);memberships.save(m);e.setStatus("ACCEPTED");e.setAcceptedAt(now);invitations.save(e);return new TenantUserSummary(m.getUsername(),identity.email(),identity.phoneNumber(),m.getRoleKey(),true,m.getCreatedAt(),m.getUpdatedAt());}
 private TenantInvitationView view(TenantInvitationEntity e){return new TenantInvitationView(e.getInvitationId(),e.getTenantKey(),e.getEmail(),e.getRoleKey(),e.getStatus(),e.getDeliveryStatus(),e.getExpiresAt(),e.getCreatedAt());}private String hash(String v){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}}
}
